rows.label:
{
          !actions.task && !actions.complete
            ? "任务信息尚未完整读取，请从任务页查看"
            : undefined
        }

rows.className:
{
                    searchHistoryEditing
                      ? "relative z-10 -my-1 -mr-1 flex shrink-0 items-center justify-center p-1"
                      : "pointer-events-none relative z-10 -my-1 -mr-1 flex shrink-0 items-center justify-center p-1 opacity-0 group-hover:pointer-events-auto group-hover:opacity-100 group-focus-within:pointer-events-auto group-focus-within:opacity-100 focus:pointer-events-auto focus:opacity-100"
                  }

rows.label:
{formatMessage(
                    { id: "search.removeHistory" },
                    { query: historyQuery },
                  )}

rows.className:
{`flex w-full items-center gap-1 py-1 pr-2 text-sm text-left hover:bg-fill-muted theme-brutal:hover:bg-black/5 transition-colors ${
            isSelected ? "bg-accent-soft theme-brutal:bg-brutal-pink/20" : ""
          }`}

{`flex w-full items-center gap-1 py-1 pr-2 text-sm text-left transition-colors ${
        isSelected
          ? "bg-accent-soft theme-brutal:bg-brutal-pink/20 border-r theme-brutal:border-r-2 border-line-strong theme-brutal:border-brutal-pink"
          : "hover:bg-fill-muted theme-brutal:hover:bg-black/5"
      }`}
